// This code has been fully generated by an AI.
//
// Personal heatmap: all tracks as translucent lines; overlapping rides add up
// visually. Filters run in the browser on the loaded GeoJSON.

import { createMap, readMapConfig, maplibregl } from "./map.js";
import { bounds } from "./map-style.js";
import { filterExpression, summarize, localNow, colorExpression, matches } from "./heatmap-data.js";

const LAYERS = ["heat-glow", "heat-line"];

export async function showHeatmap() {
  const form = document.getElementById("heatmap-filter");
  const info = document.getElementById("heatmap-info");
  const categories = JSON.parse(document.getElementById("categories").textContent);
  wireSheet(form);

  let data;
  try {
    const res = await fetch("api/tracks", { headers: { Accept: "application/geo+json" } });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    data = await res.json();
  } catch (err) {
    info.textContent = `Tracks konnten nicht geladen werden: ${err.message}`;
    info.classList.add("error");
    return;
  }
  if (!data.features.length) {
    info.textContent = "Noch keine Aktivitäten mit GPS-Daten.";
    return;
  }

  const all = data.features.flatMap((f) => f.geometry.coordinates);
  const map = await createMap(document.getElementById("map"), readMapConfig(), {
    bounds: bounds(all),
    fitBoundsOptions: { padding: 30 },
  });

  map.addSource("tracks", { type: "geojson", data });
  // Wide, faint glow plus a thin core: single rides stay visible, repeated
  // routes become bright and saturated.
  map.addLayer({
    id: "heat-glow", type: "line", source: "tracks",
    layout: { "line-join": "round", "line-cap": "round" },
    paint: {
      "line-width": ["interpolate", ["linear"], ["zoom"], 5, 3, 12, 8, 16, 16],
      "line-blur": ["interpolate", ["linear"], ["zoom"], 5, 2, 16, 8],
      "line-opacity": 0.12,
    },
  });
  map.addLayer({
    id: "heat-line", type: "line", source: "tracks",
    layout: { "line-join": "round", "line-cap": "round" },
    paint: {
      "line-width": ["interpolate", ["linear"], ["zoom"], 5, 0.8, 12, 1.8, 16, 3],
      "line-opacity": 0.45,
    },
  });

  const state = () => ({
    categories: [...form.querySelectorAll("input[name=cat]:checked")].map((i) => i.value),
    period: form.period.value,
    fromDate: form.from.value,
    toDate: form.to.value,
    color: form.color.value,
    dim: form.dim.checked,
  });

  const apply = () => {
    const s = state();
    form.querySelector(".custom-range").hidden = s.period !== "custom";
    const now = localNow();
    for (const id of LAYERS) {
      map.setFilter(id, filterExpression(s, now));
      map.setPaintProperty(id, "line-color", colorExpression(s.color, categories));
    }
    dimBasemap(map, s.dim);
    const sum = summarize(data.features, s, now);
    info.textContent = `${sum.count} Aktivität${sum.count === 1 ? "" : "en"} · ${sum.km.toLocaleString("de-DE")} km`;
  };
  form.addEventListener("change", apply);
  form.addEventListener("submit", (e) => e.preventDefault());
  form.querySelector("[data-action=fit]").addEventListener("click", () => {
    const s = state();
    const now = localNow();
    const b = bounds(data.features.filter((f) => matches(f, s, now)).flatMap((f) => f.geometry.coordinates));
    if (b) map.fitBounds(b, { padding: 30, maxZoom: 15 });
  });
  apply();

  map.on("click", (e) => showPopup(map, e));
  for (const id of LAYERS) {
    map.on("mouseenter", id, () => (map.getCanvas().style.cursor = "pointer"));
    map.on("mouseleave", id, () => (map.getCanvas().style.cursor = ""));
  }
}

/** Mobile: the filter form is a bottom sheet opened from the map toolbar. */
function wireSheet(form) {
  const opener = document.querySelector(".sheet-open");
  for (const btn of document.querySelectorAll("[data-action=sheet]")) {
    btn.addEventListener("click", () => {
      const open = form.classList.toggle("open");
      opener?.setAttribute("aria-expanded", String(open));
    });
  }
}

/** Desaturates and darkens all raster layers so the tracks stand out. */
function dimBasemap(map, on) {
  for (const layer of map.getStyle().layers) {
    if (layer.type !== "raster") continue;
    map.setPaintProperty(layer.id, "raster-saturation", on ? -0.8 : 0);
    map.setPaintProperty(layer.id, "raster-brightness-max", on ? 0.55 : 1);
  }
}

/** Lists the activities under the click, newest first, with links. */
function showPopup(map, e) {
  const box = [[e.point.x - 6, e.point.y - 6], [e.point.x + 6, e.point.y + 6]];
  const seen = new Map();
  for (const f of map.queryRenderedFeatures(box, { layers: ["heat-line"] })) seen.set(f.properties.id, f.properties);
  if (!seen.size) return;

  const items = [...seen.values()].sort((a, b) => b.t - a.t);
  const list = document.createElement("ul");
  list.className = "popup-list";
  for (const p of items.slice(0, 10)) {
    const li = document.createElement("li");
    const a = document.createElement("a");
    a.href = `activities/${p.id}`;
    a.textContent = `${new Date(p.t * 1000).toLocaleDateString("de-DE", { timeZone: "UTC" })} · ${p.label} · ${p.km.toLocaleString("de-DE")} km`;
    li.append(a);
    list.append(li);
  }
  if (items.length > 10) {
    const li = document.createElement("li");
    li.textContent = `… und ${items.length - 10} weitere`;
    list.append(li);
  }
  new maplibregl.Popup({ maxWidth: "22rem" }).setLngLat(e.lngLat).setDOMContent(list).addTo(map);
}
